/* M.V.P. Accelerator, Player-Coach track: narration text and timing cues (round 3, Dennis). Generated by _generators/cues_r3.py. */
window.NARRATION = {"ci_a": {"dur": 22.72, "text": "Pressure shows how you actually lead. This is where you start to see the gap between instinct and intention. Take about 30 seconds on each of these. Write what actually went on inside you, rather than what you think should have happened. Only you can see what you write, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead.", 0], [2.93, "This is where you start to see the gap between instinct and intention.", 0], [7.35, "Take about 30 seconds on each of these.", 1], [9.97, "Write what actually went on inside you, rather than what you think should have happened.", 1], [14.69, "Only you can see what you write, and it's saved here so you can come back to it.", 1], [19.05, "Select Save on each one as you go, then select Next.", 2]], "v": "k1", "cues": [0.03, 7.35, 19.05]}, "ci_b": {"dur": 10.8, "text": "Now look at what you wrote and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", "sents": [[0.01, "Now look at what you wrote and pick the pattern that's closest to it.", 0], [3.75, "There's no right answer.", 1], [5.23, "Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", 1]], "v": "k1", "cues": [0.01, 3.75]}, "ci_c": {"dur": 20.08, "text": "Now run the Foundation Reset. Say your five words, the ones you saved on the Foundation Reset screen. Ask yourself for two next-best steps. Pick the one you'll take in the next ten minutes. Then take one breath and answer the anchor on the last card. It takes about a minute and works best standing up, so do it now before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.15, "Say your five words, the ones you saved on the Foundation Reset screen.", 1], [6.37, "Ask yourself for two next-best steps.", 1], [9.07, "Pick the one you'll take in the next ten minutes.", 1], [11.71, "Then take one breath and answer the anchor on the last card.", 1], [15.41, "It takes about a minute and works best standing up, so do it now before you move on.", 2]], "v": "k1", "cues": [0, 2.15, 15.41]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "v4l", "cues": [0.05]}, "n_4_14": {"dur": 10.8, "text": "Time for the drill. This one is about how quickly you recover when something goes wrong. Press Play. The video pauses a few times so you can answer, and it resumes when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.47, "This one is about how quickly you recover when something goes wrong.", 0], [5.55, "Press Play.", 1], [6.65, "The video pauses a few times so you can answer, and it resumes when you're done.", 1]], "v": "k1", "cues": [0.01, 5.55]}, "pc_n_4_0": {"dur": 12.08, "text": "Lesson 4 is about the moment your plan meets pressure. You'll build your own first move for when things go wrong, then learn to coach your team through resistance and change. Select Start Lesson.", "sents": [[0.03, "Lesson 4 is about the moment your plan meets pressure.", 0], [4.01, "You'll build your own first move for when things go wrong, then learn to coach your team through resistance and change.", 1], [10.55, "Select Start Lesson.", 1]], "v": "r3L", "cues": [0.03, 4.01]}, "pc_n_4_1": {"dur": 13.68, "text": "Read this moment and notice your own first instinct. What you do in the next ten minutes sets your team's stress level for the month. This lesson gives you a first move for yourself and two coaching questions for what comes after.", "sents": [[0, "Read this moment and notice your own first instinct.", 0], [4.03, "What you do in the next ten minutes sets your team's stress level for the month.", 1], [8.51, "This lesson gives you a first move for yourself and two coaching questions for what comes after.", 1]], "v": "r3L", "cues": [0, 4.03]}, "pc_n_4_10": {"dur": 26.88, "text": "Here's the example from the video. A manager rolled out new software, and her team was slow to use it. Instead of pushing harder, she held one-on-ones and asked what worried them most about the new system. It turned out they were afraid they wouldn't learn it fast enough and would look incompetent. That was the fear to address. Diagnose first. Your Playbook asks you to pick one change on your team and name the loss behind the resistance.", "sents": [[0.01, "Here's the example from the video.", 0], [2.17, "A manager rolled out new software, and her team was slow to use it.", 1], [6.75, "Instead of pushing harder, she held one-on-ones and asked what worried them most about the new system.", 2], [12.79, "It turned out they were afraid they wouldn't learn it fast enough and would look incompetent.", 3], [17.51, "That was the fear to address.", 3], [19.71, "Diagnose first.", 4], [21.57, "Your Playbook asks you to pick one change on your team and name the loss behind the resistance.", 4]], "v": "pc1", "cues": [0.01, 2.17, 6.75, 12.79, 19.71]}, "pc_n_4_12": {"dur": 9.68, "text": "Now try the agility question in a tense moment. Your Athleader is upset, and a quick fix is tempting. Pick your first sentence, and you'll hear where it leads.", "sents": [[0.05, "Now try the agility question in a tense moment.", 0], [3.33, "Your Athleader is upset, and a quick fix is tempting.", 1], [6.95, "Pick your first sentence, and you'll hear where it leads.", 1]], "v": "r3L", "cues": [0.05, 3.33]}, "pc_n_4_12_o0": {"dur": 9.36, "text": "You've solved it, and quickly. You've also taught them that panicking gets you to solve it, so next time they'll come to you sooner. Try the other option to compare.", "sents": [[0.01, "You've solved it, and quickly.", 0], [2.35, "You've also taught them that panicking gets you to solve it, so next time they'll come to you sooner.", 0], [7.71, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_4_12_o1": {"dur": 10.16, "text": "One question moves them from panic to problem-solving, and the answer they find is theirs. That's the shift from chief problem solver to chief question asker.", "sents": [[0, "One question moves them from panic to problem-solving, and the answer they find is theirs.", 0], [6.07, "That's the shift from chief problem solver to chief question asker.", 0]], "v": "r3", "cues": [0]}, "pc_n_4_14": {"dur": 32.88, "text": "Your core rep this week happens inside real work: use the agility question in one real conversation and note what changed when you asked a question instead of providing a solution. If you have more time, write your own first move: what triggers it, what you'll do for ten minutes, and where you'll do it. And identify one resistance on your team, name which loss is behind it, and write the questions you'll ask in a one-on-one. Run your core rep, then ask the person you coached how it landed. Select Open your Lesson 4 pages to get started.", "sents": [[0.01, "Your core rep this week happens inside real work: use the agility question in one real conversation and note what changed when you asked a question instead of providing a solution.", 0], [11.49, "If you have more time, write your own first move: what triggers it, what you'll do for ten minutes, and where you'll do it.", 1], [18.57, "And identify one resistance on your team, name which loss is behind it, and write the questions you'll ask in a one-on-one.", 2], [26.05, "Run your core rep, then ask the person you coached how it landed.", 3], [29.91, "Select Open your Lesson 4 pages to get started.", 3]], "v": "pc1", "cues": [0.01, 11.49, 18.57, 26.05]}, "pc_n_4_15": {"dur": 12.56, "text": "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist. His work sits where neuroscience meets peak performance, and his drill is one you run with your team. Press Play to hear from him.", "sents": [[0, "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist.", 0], [5.01, "His work sits where neuroscience meets peak performance, and his drill is one you run with your team.", 1], [11.19, "Press Play to hear from him.", 1]], "v": "r3L", "cues": [0, 5.01]}, "pc_n_4_16": {"dur": 15.12, "text": "Michael's drill builds team resilience, and it's designed to be done with your team. It takes about three minutes. Select Start the timer and take the team through each step. When you've completed the drill or scheduled a time to run it, select the option that fits.", "sents": [[0.07, "Michael's drill builds team resilience, and it's designed to be done with your team.", 0], [5.19, "It takes about three minutes.", 0], [6.89, "Select Start the timer and take the team through each step.", 1], [10.49, "When you've completed the drill or scheduled a time to run it, select the option that fits.", 1]], "v": "pc1", "cues": [0.07, 6.89]}, "pc_n_4_18_q0": {"dur": 8.96, "text": "A few questions on the main ideas. First: a team member keeps forgetting to use the new process. What does diagnosing the resistance mean?", "sents": [[0, "A few questions on the main ideas.", 0], [2.19, "First: a team member keeps forgetting to use the new process.", 0], [6.59, "What does diagnosing the resistance mean?", 0]], "v": "r3L", "cues": [0]}, "pc_n_4_18_q1": {"dur": 3.04, "text": "What is the purpose of your ten-minute first move?", "sents": [[0.07, "What is the purpose of your ten-minute first move?", 0]], "v": "r3", "cues": [0.07]}, "pc_n_4_18_q2": {"dur": 7.52, "text": "Your Athleader's ninety-day goal is at risk after a reorganization, and they want to give up. What's your best first move?", "sents": [[0.01, "Your Athleader's ninety-day goal is at risk after a reorganization, and they want to give up.", 0], [5.83, "What's your best first move?", 0]], "v": "r3L", "cues": [0.01]}, "pc_n_4_18_q3": {"dur": 7.36, "text": "Last one. Which fear is most likely behind this line: I don't know what this change means for my role?", "sents": [[0.03, "Last one.", 0], [1.19, "Which fear is most likely behind this line: I don't know what this change means for my role?", 0]], "v": "r3L", "cues": [0.03]}, "pc_n_4_18_w0": {"dur": 10.16, "text": "Resistance is usually about a loss: certainty, competence, or connection. Once you know which one, you can address it directly instead of pushing harder.", "sents": [[0.05, "Resistance is usually about a loss: certainty, competence, or connection.", 0], [5.77, "Once you know which one, you can address it directly instead of pushing harder.", 0]], "v": "r3L", "cues": [0.05]}, "pc_n_4_18_w1": {"dur": 9.36, "text": "Your team takes its cue from you. A short, repeatable pause lets you decide from clarity, so you bring a question to the meeting rather than your stress.", "sents": [[0.01, "Your team takes its cue from you.", 0], [2.55, "A short, repeatable pause lets you decide from clarity, so you bring a question to the meeting rather than your stress.", 0]], "v": "r3", "cues": [0.01]}, "pc_n_4_18_w2": {"dur": 6.8, "text": "The agility question moves them from frustration to options, and whatever they come up with is theirs to own.", "sents": [[0.05, "The agility question moves them from frustration to options, and whatever they come up with is theirs to own.", 0]], "v": "r3L", "cues": [0.05]}, "pc_n_4_18_w3": {"dur": 7.52, "text": "Not knowing what happens next is a loss of certainty. Ask what their biggest unknown is, and answer what you can.", "sents": [[0, "Not knowing what happens next is a loss of certainty.", 0], [3.77, "Ask what their biggest unknown is, and answer what you can.", 0]], "v": "r3", "cues": [0]}, "pc_n_4_19": {"dur": 31.76, "text": "Before you go, here's what to keep from this lesson. Put ten minutes between the pressure and your response. Separate the emotion from the data and then decide. When people resist, find out what they're afraid of losing: certainty, competence, or connection. Address that first. And when your Athleader brings you a problem, ask what the constraint makes possible before you offer an answer. Select Download my answers for a Word document containing what you wrote today. Chapter 7 of the book goes further on agility.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.39, "Put ten minutes between the pressure and your response.", 1], [6.73, "Separate the emotion from the data and then decide.", 1], [10.39, "When people resist, find out what they're afraid of losing: certainty, competence, or connection.", 2], [16.65, "Address that first.", 2], [18.39, "And when your Athleader brings you a problem, ask what the constraint makes possible before you offer an answer.", 3], [24.55, "Select Download my answers for a Word document containing what you wrote today.", 4], [28.97, "Chapter 7 of the book goes further on agility.", 4]], "v": "pc1", "cues": [0.03, 3.39, 10.39, 18.39, 24.55]}, "pc_n_4_20": {"dur": 18.08, "text": "That's Lesson 4 done. Four lessons down, and you're asking more questions than you're offering solutions. This week, run your core rep: use the agility question in one real conversation and ask how it landed. Next time, the long game: your energy and how your team recovers.", "sents": [[0.03, "That's Lesson 4 done.", 0], [1.97, "Four lessons down, and you're asking more questions than you're offering solutions.", 0], [6.73, "This week, run your core rep: use the agility question in one real conversation and ask how it landed.", 1], [13.63, "Next time, the long game: your energy and how your team recovers.", 1]], "v": "pc1", "cues": [0.03, 6.73]}, "pc_n_4_3": {"dur": 6.4, "text": "A quick look back at Lesson 3 before you start. Choose the answer you remember. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 3 before you start.", 0], [2.95, "Choose the answer you remember.", 1], [4.85, "This one isn't scored.", 1]], "v": "r3L", "cues": [0, 2.95]}, "pc_n_4_4": {"dur": 30.96, "text": "Here's what you'll practice in this lesson. You'll define your own first move under pressure: one short, repeatable action that separates the emotion from the data before you decide anything. When people resist a change, you'll learn to ask what they're afraid of losing. Melissa names three things: certainty, competence, and connection. You'll add one agility question to your coaching and ask it before you offer a solution. And you'll use it in one real conversation. That's your core rep this week.", "sents": [[0, "Here's what you'll practice in this lesson.", 0], [2.35, "You'll define your own first move under pressure: one short, repeatable action that separates the emotion from the data before you decide anything.", 1], [11.91, "When people resist a change, you'll learn to ask what they're afraid of losing.", 2], [16.39, "Melissa names three things: certainty, competence, and connection.", 2], [21.17, "You'll add one agility question to your coaching and ask it before you offer a solution.", 3], [26.37, "And you'll use it in one real conversation.", 4], [29.41, "That's your core rep this week.", 4]], "v": "r3", "cues": [0, 2.35, 11.91, 21.17, 26.37]}, "pc_n_4_7": {"dur": 34.72, "text": "Here's how the CEO's ten-minute walk works as a play you can repeat. First, notice what you reach for when the bad news lands. For many managers, it's a meeting or a fast email. Then put ten minutes between the news and your response. A walk, a page of notes, or a closed door, whatever lets you separate the emotion from the data. Decide what to do after that. If you still need the meeting, open it with a question rather than a plan. And repeat it every time until it's your default. In Drill 4.2 of your Playbook, write down your own first move.", "sents": [[0, "Here's how the CEO's ten-minute walk works as a play you can repeat.", 0], [4.31, "First, notice what you reach for when the bad news lands.", 1], [8.21, "For many managers, it's a meeting or a fast email.", 1], [11.53, "Then put ten minutes between the news and your response.", 2], [15.17, "A walk, a page of notes, or a closed door, whatever lets you separate the emotion from the data.", 2], [21.27, "Decide what to do after that.", 3], [23.27, "If you still need the meeting, open it with a question rather than a plan.", 3], [27.37, "And repeat it every time until it's your default.", 4], [30.65, "In Drill 4.2 of your Playbook, write down your own first move.", 4]], "v": "pc1", "cues": [0, 4.31, 11.53, 21.27, 27.37]}, "pc_n_4_9": {"dur": 12.64, "text": "Resistance to change is rarely about the change itself. It's usually about what people fear they'll lose. Select each one to hear how it sounds and what to ask. Open all three before you move on.", "sents": [[0.03, "Resistance to change is rarely about the change itself.", 0], [3.95, "It's usually about what people fear they'll lose.", 0], [7.05, "Select each one to hear how it sounds and what to ask.", 1], [10.57, "Open all three before you move on.", 1]], "v": "r3", "cues": [0.03, 7.05]}, "pc_n_4_9_certainty": {"dur": 11.44, "text": "Certainty is about not knowing. You'll hear it as questions about timing, roles and what happens next. Ask what the biggest unknown is for them, and answer what you can.", "sents": [[0.09, "Certainty is about not knowing.", 0], [2.83, "You'll hear it as questions about timing, roles and what happens next.", 0], [7.41, "Ask what the biggest unknown is for them, and answer what you can.", 0]], "v": "r3", "cues": [0.09]}, "pc_n_4_9_competence": {"dur": 11.52, "text": "Competence is the fear of looking slow or getting it wrong. That was the software team in the video. Ask what they'd need to feel ready, whether that's training time or permission to be slow for a while.", "sents": [[0.07, "Competence is the fear of looking slow or getting it wrong.", 0], [4.13, "That was the software team in the video.", 0], [6.21, "Ask what they'd need to feel ready, whether that's training time or permission to be slow for a while.", 0]], "v": "r3", "cues": [0.07]}, "pc_n_4_9_connection": {"dur": 10.72, "text": "Connection is about people. A change can split a team or move someone away from colleagues they rely on. Ask what they're most worried about losing, and look for a way to keep it.", "sents": [[0.03, "Connection is about people.", 0], [2.23, "A change can split a team or move someone away from colleagues they rely on.", 0], [6.85, "Ask what they're most worried about losing, and look for a way to keep it.", 0]], "v": "r3L", "cues": [0.03]}, "r2_code_pulse": {"dur": 7.36, "text": "Type the code from the last page of the Pulse Check, then select Submit. A quick knowledge check comes next, then your recap.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.23, "A quick knowledge check comes next, then your recap.", 0]], "v": "r3", "cues": [0.01]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 21.36, "text": "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season. It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next, and it opens right here.", "sents": [[0.01, "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season.", 0], [6.57, "It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks.", 1], [12.25, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [18.83, "Select Next, and it opens right here.", 2]], "v": "k1", "cues": [0.01, 6.57, 12.25]}};
